begin;
create table private.learning_goals(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.teaching_classes(id),code text not null check(length(trim(code)) between 1 and 30),title text not null check(length(trim(title)) between 2 and 1000),threshold numeric not null check(threshold between 0 and 100),active boolean not null default true,revision int not null default 0,unique(course_id,code));
create table private.goal_links(goal_id uuid not null references private.learning_goals(id) on delete cascade,kind text not null check(kind in ('material','assignment','quiz')),activity_id uuid not null,primary key(goal_id,kind,activity_id));
create index goal_links_activity on private.goal_links(kind,activity_id);
create table private.study_followups(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.teaching_classes(id),student_id uuid not null references public.profiles(id) on delete cascade,kind text not null check(kind in ('remedial','enrichment')),activity_kind text not null check(activity_kind in ('assignment','quiz')),activity_id uuid not null,plan text not null check(length(trim(plan)) between 5 and 3000),due_on date not null,policy text not null check(policy in ('preserve','highest','latest','capped')),cap numeric not null default 75 check(cap between 0 and 100),status text not null default 'planned' check(status in ('planned','completed','withdrawn')),base_signature text,result_score numeric check(result_score between 0 and 100),note text not null default '' check(length(note)<=3000),revision int not null default 0,created_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),check(kind<>'enrichment' or policy='preserve'));
create index followups_scope on private.study_followups(course_id,student_id,activity_kind,activity_id,updated_at desc);create index followups_actor on private.study_followups(created_by);
create table private.grade_finalizations(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.teaching_classes(id),actor_id uuid references public.profiles(id) on delete set null,reason text not null check(length(trim(reason)) between 5 and 1000),created_at timestamptz not null default clock_timestamp());
create index finalizations_course on private.grade_finalizations(course_id,created_at desc);create index finalizations_actor on private.grade_finalizations(actor_id);
create table private.final_grade_rows(finalization_id uuid not null references private.grade_finalizations(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,score numeric not null,primary key(finalization_id,student_id));create index final_grade_student on private.final_grade_rows(student_id);
create table private.course_grade_state(course_id uuid primary key references public.teaching_classes(id),locked boolean not null default false,revision int not null default 0,finalization_id uuid references private.grade_finalizations(id));create index grade_state_finalization on private.course_grade_state(finalization_id);
create table private.grade_revisions(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.teaching_classes(id),student_id uuid not null references public.profiles(id) on delete cascade,kind text not null,version_id uuid references public.learning_submission_versions(id) on delete cascade,attempt_id uuid references public.learning_quiz_attempts(id) on delete cascade,position int,old_score numeric,new_score numeric,reason text not null default '',actor_id uuid references public.profiles(id) on delete set null,created_at timestamptz not null default clock_timestamp());
create index grade_revision_course on private.grade_revisions(course_id,created_at desc,id);create index grade_revision_student on private.grade_revisions(student_id);create index grade_revision_version on private.grade_revisions(version_id);create index grade_revision_attempt on private.grade_revisions(attempt_id);create index grade_revision_actor on private.grade_revisions(actor_id);
create table private.academic_rollovers(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id),actor_id uuid references public.profiles(id) on delete set null,source_id uuid not null references public.classrooms(id),destination_id uuid not null references public.classrooms(id),mode text not null check(mode in ('semester','promotion')),status text not null default 'preview' check(status in ('preview','committed')),fingerprint text not null,participant_count int not null,created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null default clock_timestamp()+interval '20 minutes',committed_at timestamptz);
create index rollovers_school on private.academic_rollovers(school_id,created_at desc);create index rollovers_actor on private.academic_rollovers(actor_id);create index rollovers_source on private.academic_rollovers(source_id);create index rollovers_destination on private.academic_rollovers(destination_id);
create table private.rollover_entries(run_id uuid not null references private.academic_rollovers(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,source_enrollment_id uuid not null references public.student_enrollments(id) on delete cascade,destination_enrollment_id uuid references public.student_enrollments(id) on delete set null,primary key(run_id,student_id));create index rollover_entries_student on private.rollover_entries(student_id);create index rollover_entries_source on private.rollover_entries(source_enrollment_id);create index rollover_entries_destination on private.rollover_entries(destination_enrollment_id);
do $$declare t text;begin foreach t in array array['learning_goals','goal_links','study_followups','grade_finalizations','final_grade_rows','course_grade_state','grade_revisions','academic_rollovers','rollover_entries'] loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated',t);execute format('grant all on private.%I to service_role',t);end loop;end;$$;
create function private.flow_share(cid uuid) returns void language plpgsql security definer set search_path='' as $$begin if cid is not null then perform pg_advisory_xact_lock_shared(hashtextextended(cid::text,2401));end if;end;$$;
create function private.flow_assert_open(cid uuid) returns void language plpgsql security definer set search_path='' as $$begin perform private.flow_share(cid);if exists(select 1 from private.course_grade_state where course_id=cid and locked) then raise exception 'Nilai final terkunci. Minta admin atau kepala madrasah membuka kembali dengan alasan.';end if;end;$$;
create function private.flow_guard() returns trigger language plpgsql security definer set search_path='' as $$declare cid uuid;r jsonb:=to_jsonb(new);begin
 if tg_table_name in ('learning_assignments','learning_quizzes') then cid:=(r->>'teaching_class_id')::uuid;if tg_op='UPDATE' and (to_jsonb(new)-array['grades_visible','explanations_visible','updated_at'])=(to_jsonb(old)-array['grades_visible','explanations_visible','updated_at']) then return new;end if;
 elsif tg_table_name='course_weights' then cid:=(r->>'course_id')::uuid;if tg_op='INSERT' and exists(select 1 from private.course_weights w where w.course_id=cid and w.assignment_weight=new.assignment_weight and w.quiz_weight=new.quiz_weight) then return new;end if;if tg_op='UPDATE' and (to_jsonb(new)-'visible')=(to_jsonb(old)-'visible') then return new;end if;
 elsif tg_table_name in ('learning_grades','rubric_marks') then select a.teaching_class_id into cid from public.learning_submission_versions v join public.learning_submissions s on s.id=v.submission_id join public.learning_assignments a on a.id=s.assignment_id where v.id=(r->>'version_id')::uuid;
 elsif tg_table_name='learning_submissions' then select teaching_class_id into cid from public.learning_assignments where id=(r->>'assignment_id')::uuid;
 elsif tg_table_name in ('learning_quiz_attempts','quiz_questions') then select teaching_class_id into cid from public.learning_quizzes where id=(r->>'quiz_id')::uuid;
 elsif tg_table_name='quiz_essay_marks' then select q.teaching_class_id into cid from public.learning_quiz_attempts a join public.learning_quizzes q on q.id=a.quiz_id where a.id=(r->>'attempt_id')::uuid;end if;
 perform private.flow_assert_open(cid);return new;
end;$$;
do $$declare t text;begin foreach t in array array['learning_assignments','learning_quizzes','learning_grades','learning_submissions','learning_quiz_attempts'] loop execute format('create trigger flow_grade_guard before insert or update on public.%I for each row execute function private.flow_guard()',t);end loop;foreach t in array array['course_weights','rubric_marks','quiz_essay_marks','quiz_questions'] loop execute format('create trigger flow_grade_guard before insert or update on private.%I for each row execute function private.flow_guard()',t);end loop;end;$$;
create function private.flow_grade_audit() returns trigger language plpgsql security definer set search_path='' as $$declare cid uuid;student uuid;why text;begin
 if tg_op='UPDATE' and new.score=old.score and new.feedback=old.feedback then return new;end if;
 if tg_table_name='learning_grades' then why:=new.reason;select a.teaching_class_id,s.student_id into cid,student from public.learning_submission_versions v join public.learning_submissions s on s.id=v.submission_id join public.learning_assignments a on a.id=s.assignment_id where v.id=new.version_id;
 else why:=coalesce(current_setting('lms.grade_reason',true),'');select q.teaching_class_id,a.student_id into cid,student from public.learning_quiz_attempts a join public.learning_quizzes q on q.id=a.quiz_id where a.id=new.attempt_id;end if;
 if tg_op='UPDATE' and length(trim(why))<5 then raise exception 'Koreksi nilai atau umpan balik wajib disertai alasan minimal 5 karakter.';end if;
 if tg_table_name='learning_grades' then insert into private.grade_revisions(course_id,student_id,kind,version_id,old_score,new_score,reason,actor_id) values(cid,student,'assignment',new.version_id,case when tg_op='UPDATE' then old.score end,new.score,why,new.graded_by);
 else insert into private.grade_revisions(course_id,student_id,kind,attempt_id,position,old_score,new_score,reason,actor_id) values(cid,student,'essay',new.attempt_id,new.position,case when tg_op='UPDATE' then old.score end,new.score,why,new.graded_by);end if;return new;end;$$;
create trigger flow_grade_history after insert or update on public.learning_grades for each row execute function private.flow_grade_audit();create trigger flow_essay_history after insert or update on private.quiz_essay_marks for each row execute function private.flow_grade_audit();
insert into private.grade_revisions(course_id,student_id,kind,version_id,new_score,reason,actor_id,created_at) select a.teaching_class_id,s.student_id,'assignment',g.version_id,g.score,'Snapshot nilai sebelum penyempurnaan alur akademik',g.graded_by,g.updated_at from public.learning_grades g join public.learning_submission_versions v on v.id=g.version_id join public.learning_submissions s on s.id=v.submission_id join public.learning_assignments a on a.id=s.assignment_id;
insert into private.grade_revisions(course_id,student_id,kind,attempt_id,position,new_score,reason,actor_id) select q.teaching_class_id,a.student_id,'essay',g.attempt_id,g.position,g.score,'Snapshot esai sebelum penyempurnaan alur akademik',g.graded_by from private.quiz_essay_marks g join public.learning_quiz_attempts a on a.id=g.attempt_id join public.learning_quizzes q on q.id=a.quiz_id;
create function private.flow_activity(cid uuid,k text,activity uuid,student uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin
 if k='assignment' then select jsonb_build_object('score',g.score/a.max_score*100,'signature',md5(jsonb_build_array(s.latest_version_id,g.score,g.updated_at,a.max_score)::text),'visible',a.grades_visible and private.learning_published(a.status,a.publish_at)) into result from public.learning_assignments a left join public.learning_submissions s on s.assignment_id=a.id and s.student_id=student left join public.learning_grades g on g.version_id=s.latest_version_id where a.id=activity and a.teaching_class_id=cid;
 elsif k='quiz' then select jsonb_build_object('score',(select max(t.score/t.max_score*100) from public.learning_quiz_attempts t where t.quiz_id=q.id and t.student_id=student and t.status<>'working'),'signature',md5(coalesce((select jsonb_agg(jsonb_build_array(t.id,t.score,t.max_score,t.status) order by t.id) from public.learning_quiz_attempts t where t.quiz_id=q.id and t.student_id=student and t.status<>'working'),'[]')::text),'visible',q.grades_visible and q.status='published') into result from public.learning_quizzes q where q.id=activity and q.teaching_class_id=cid;end if;return result;end;$$;
create function private.flow_effective(cid uuid,k text,activity uuid,student uuid) returns numeric language plpgsql stable security definer set search_path='' as $$declare base jsonb;f private.study_followups;v numeric;begin base:=private.flow_activity(cid,k,activity,student);v:=(base->>'score')::numeric;if v is null then return null;end if;select * into f from private.study_followups where course_id=cid and activity_kind=k and activity_id=activity and student_id=student and status='completed' and kind='remedial' and base_signature=base->>'signature' order by updated_at desc,id desc limit 1;if f.id is null or f.policy='preserve' then return v;elsif f.policy='highest' then return greatest(v,f.result_score);elsif f.policy='latest' then return f.result_score;else return greatest(v,least(f.result_score,f.cap));end if;end;$$;
create function private.flow_adjust_report(r jsonb,cid uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare c jsonb;w private.course_weights;gs private.course_grade_state;outrows jsonb:='[]';x jsonb;aa numeric;qa numeric;final numeric;begin perform private.flow_share(cid);c:=private.learning_context(cid);select * into w from private.course_weights where course_id=cid;select * into gs from private.course_grade_state where course_id=cid;
 for x in select * from jsonb_array_elements(r->'rows') loop
 if not exists(select 1 from public.profiles where id=(x->>'id')::uuid and status='active') then continue;end if;
 select round(avg(private.flow_effective(cid,'assignment',a.id,(x->>'id')::uuid)),2) into aa from public.learning_assignments a where a.teaching_class_id=cid and private.learning_published(a.status,a.publish_at) and ((c->>'reviewer')::boolean or a.grades_visible) and exists(select 1 from public.learning_submissions s join public.learning_grades g on g.version_id=s.latest_version_id where s.assignment_id=a.id and s.student_id=(x->>'id')::uuid);
 select round(avg(private.flow_effective(cid,'quiz',q.id,(x->>'id')::uuid)),2) into qa from public.learning_quizzes q where q.teaching_class_id=cid and q.status='published' and ((c->>'reviewer')::boolean or q.grades_visible) and exists(select 1 from public.learning_quiz_attempts a where a.quiz_id=q.id and a.student_id=(x->>'id')::uuid and a.status<>'working' and a.score is not null);
 final:=case when x->>'weighted_final' is not null and (w.assignment_weight=0 or aa is not null) and (w.quiz_weight=0 or qa is not null) then round(coalesce(aa,0)*w.assignment_weight/100+coalesce(qa,0)*w.quiz_weight/100,2) end;if gs.locked and final is not null then select score into final from private.final_grade_rows where finalization_id=gs.finalization_id and student_id=(x->>'id')::uuid;end if;
 outrows:=outrows||jsonb_build_array(x||jsonb_build_object('assignment_average',aa,'quiz_average',qa,'final_locked',coalesce(gs.locked,false))||case when x?'weighted_final' then jsonb_build_object('weighted_final',final) else '{}'::jsonb end);end loop;return r||jsonb_build_object('rows',outrows,'final_locked',coalesce(gs.locked,false));end;$$;
alter function private.weighted_report(jsonb) rename to weighted_report_pre_flow;
create function private.weighted_report(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$begin return private.flow_adjust_report(private.weighted_report_pre_flow(p),(p->>'course')::uuid);end;$$;
alter function private.learning_report(jsonb) rename to learning_report_pre_flow;
create function private.learning_report(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$begin return private.flow_adjust_report(private.learning_report_pre_flow(p),(p->>'course')::uuid);end;$$;
create function private.flow_rollover_plan(school uuid,source uuid,destination uuid,mode text,students uuid[]) returns jsonb language plpgsql security definer set search_path='' as $$declare src record;dst record;rows jsonb;begin
 if coalesce(cardinality(students),0) not between 1 and 500 or cardinality(students)<>(select count(distinct x) from unnest(students) x) then raise exception 'Pilih 1–500 siswa tanpa duplikasi.';end if;
 select c.*,s.starts_on,s.ends_on,s.academic_year_id,s.number,s.status as semester_status,g.number as grade_number into src from public.classrooms c join public.semesters s on s.id=c.semester_id join public.grade_levels g on g.id=c.grade_level_id where c.id=source and c.school_id=school;
 select c.*,s.starts_on,s.ends_on,s.academic_year_id,s.number,s.status as semester_status,g.number as grade_number into dst from public.classrooms c join public.semesters s on s.id=c.semester_id join public.grade_levels g on g.id=c.grade_level_id where c.id=destination and c.school_id=school;
 if src.id is null or dst.id is null or src.semester_id=dst.semester_id or src.semester_status not in ('active','archived') or dst.semester_status<>'draft' or dst.starts_on<=src.ends_on then raise exception 'Pilih semester asal aktif/arsip dan semester tujuan Draf setelah semester asal.';end if;
 if mode='semester' then if src.academic_year_id<>dst.academic_year_id or src.number<>1 or dst.number<>2 or src.grade_number<>dst.grade_number then raise exception 'Pergantian semester harus Ganjil ke Genap pada tahun dan tingkat yang sama.';end if;
 elsif mode='promotion' then if src.academic_year_id=dst.academic_year_id or src.number<>2 or dst.number<>1 or dst.grade_number not in (src.grade_number,src.grade_number+1) then raise exception 'Kenaikan kelas harus Genap ke Ganjil tahun berikutnya; tingkat sama untuk mengulang atau naik satu tingkat.';end if;else raise exception 'Mode perpindahan tidak valid.';end if;
 if exists(select 1 from unnest(students) uid where not exists(select 1 from public.student_enrollments e join public.profiles pr on pr.id=e.student_id join public.school_memberships m on m.user_id=pr.id and m.school_id=e.school_id join public.membership_roles mr on mr.membership_id=m.id and mr.school_id=m.school_id and mr.role_code='student' where e.school_id=school and e.classroom_id=source and e.student_id=uid and e.status='active' and pr.status='active' and m.status='active')) then raise exception 'Peserta berubah, nonaktif, atau bukan anggota aktif rombel asal. Buat pratinjau baru.';end if;
 if exists(select 1 from public.student_enrollments where school_id=school and semester_id=dst.semester_id and student_id=any(students) and (status='active' or classroom_id=destination)) then raise exception 'Sebagian siswa sudah memiliki keanggotaan tujuan. Periksa Anggota kelas.';end if;
 select jsonb_agg(jsonb_build_object('student_id',pr.id,'source_enrollment_id',e.id,'source_updated_at',e.updated_at,'profile_updated_at',pr.updated_at) order by pr.id) into rows from public.student_enrollments e join public.profiles pr on pr.id=e.student_id where e.classroom_id=source and e.status='active' and e.student_id=any(students);
 return jsonb_build_object('source',to_jsonb(src),'destination',to_jsonb(dst),'mode',mode,'rows',rows);end;$$;
create function private.flow_rollover(cmd text,p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare v_school uuid:=(p->>'school')::uuid;v_actor uuid:=auth.uid();v_target uuid:=(p->>'target')::uuid;v_d jsonb:=coalesce(p->'data','{}');v_students uuid[];v_plan jsonb;v_run private.academic_rollovers;v_item jsonb;v_e uuid;v_off int:=greatest(0,least(coalesce((p->>'offset')::int,0),100000));begin
 if not private.has_school_role(v_school,'admin') then raise exception 'Hanya admin sekolah dapat mengelola perpindahan periode.' using errcode='42501';end if;perform 1 from public.schools where id=v_school for update;
 if cmd='rollover-list' then return jsonb_build_object('runs',(select coalesce(jsonb_agg(x order by x.created_at desc),'[]') from (select ar.id,ar.mode,ar.status,ar.participant_count,ar.created_at,ar.committed_at,a.name as source,b.name as destination from private.academic_rollovers ar join public.classrooms a on a.id=ar.source_id join public.classrooms b on b.id=ar.destination_id where ar.school_id=v_school order by ar.created_at desc,ar.id limit 26 offset v_off) x));end if;
 if cmd='rollover-preview' then delete from private.academic_rollovers where school_id=v_school and status='preview' and expires_at<clock_timestamp()-interval '1 day';v_students:=array(select value::uuid from jsonb_array_elements_text(v_d->'students'));v_plan:=private.flow_rollover_plan(v_school,(v_d->>'source')::uuid,(v_d->>'destination')::uuid,v_d->>'mode',v_students);
 insert into private.academic_rollovers(school_id,actor_id,source_id,destination_id,mode,fingerprint,participant_count) values(v_school,v_actor,(v_d->>'source')::uuid,(v_d->>'destination')::uuid,v_d->>'mode',md5(v_plan::text),cardinality(v_students)) returning * into v_run;insert into private.rollover_entries(run_id,student_id,source_enrollment_id) select v_run.id,(x->>'student_id')::uuid,(x->>'source_enrollment_id')::uuid from jsonb_array_elements(v_plan->'rows') x;
 else select * into v_run from private.academic_rollovers where id=v_target and school_id=v_school for update;if not found then raise exception 'Pratinjau tidak ditemukan.' using errcode='42501';end if;
 if cmd='rollover-commit' and v_run.status<>'committed' then
 if v_run.actor_id<>v_actor or v_run.expires_at<=clock_timestamp() or v_d->>'confirmation' is distinct from 'PINDAHKAN PESERTA' then raise exception 'Konfirmasi atau pratinjau tidak berlaku. Buat pratinjau baru.';end if;
 select array_agg(student_id order by student_id) into v_students from private.rollover_entries where run_id=v_run.id;if coalesce(cardinality(v_students),0)<>v_run.participant_count then raise exception 'Peserta berubah. Buat pratinjau baru.';end if;
 perform 1 from public.profiles where id=any(v_students) order by id for share;v_plan:=private.flow_rollover_plan(v_school,v_run.source_id,v_run.destination_id,v_run.mode,v_students);if md5(v_plan::text)<>v_run.fingerprint then raise exception 'Data berubah sejak pratinjau. Buat pratinjau baru.';end if;
 for v_item in select * from jsonb_array_elements(v_plan->'rows') loop insert into public.student_enrollments(school_id,classroom_id,semester_id,student_id,status) values(v_school,v_run.destination_id,(v_plan->'destination'->>'semester_id')::uuid,(v_item->>'student_id')::uuid,'active') returning id into v_e;update private.rollover_entries set destination_enrollment_id=v_e where run_id=v_run.id and student_id=(v_item->>'student_id')::uuid;end loop;
 update private.academic_rollovers set status='committed',committed_at=clock_timestamp() where id=v_run.id returning * into v_run;insert into public.audit_logs(school_id,actor_id,action,entity,entity_id,details) values(v_school,v_actor,'academic.rollover','academic_rollovers',v_run.id::text,jsonb_build_object('count',v_run.participant_count,'source',v_run.source_id,'destination',v_run.destination_id));
 elsif cmd not in ('rollover-commit','rollover-detail') then raise exception 'Tindakan tidak dikenal.';end if;end if;
 return jsonb_build_object('run',to_jsonb(v_run)-'fingerprint','readiness',jsonb_build_object('unfinalized_courses',(select count(*) from public.teaching_classes t where t.classroom_id=v_run.source_id and t.active and not exists(select 1 from private.course_grade_state gst where gst.course_id=t.id and gst.locked)),'working_quizzes',(select count(*) from public.learning_quiz_attempts a join public.learning_quizzes q on q.id=a.quiz_id join public.teaching_classes t on t.id=q.teaching_class_id where t.classroom_id=v_run.source_id and a.status='working')),'rows',(select coalesce(jsonb_agg(jsonb_build_object('student_id',pr.id,'full_name',pr.full_name,'source_enrollment_id',e.source_enrollment_id,'destination_enrollment_id',e.destination_enrollment_id,'source_exists',se.id is not null,'destination_status',de.status) order by pr.full_name,pr.id),'[]') from private.rollover_entries e join public.profiles pr on pr.id=e.student_id and pr.status='active' left join public.student_enrollments se on se.id=e.source_enrollment_id left join public.student_enrollments de on de.id=e.destination_enrollment_id where e.run_id=v_run.id));end;$$;
create function private.academic_flow_command(cmd text,p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare v_actor uuid:=auth.uid();v_cid uuid:=(p->>'course')::uuid;v_school uuid;v_target uuid:=(p->>'target')::uuid;v_d jsonb:=coalesce(p->'data','{}');v_c jsonb;v_gs private.course_grade_state;v_g private.learning_goals;v_f private.study_followups;v_report jsonb;v_page jsonb;v_all jsonb:='[]';v_row jsonb;v_goal record;v_metrics jsonb;v_score numeric;v_required int;v_recorded int;v_visible boolean;v_fid uuid;v_idx int;v_rev int:=coalesce((v_d->>'revision')::int,0);v_reason text:=trim(coalesce(v_d->>'reason',''));v_kind text;v_activity uuid;v_base jsonb;v_off int:=greatest(0,least(coalesce((p->>'offset')::int,0),100000));begin
 perform private.require_mfa();if not private.account_ready() then raise exception 'Selesaikan aktivasi akun.' using errcode='42501';end if;
 if cmd like 'rollover-%' then return private.flow_rollover(cmd,p);end if;
 v_c:=private.learning_context(v_cid);if v_c is null then raise exception 'Kelas tidak dapat diakses.' using errcode='42501';end if;v_school:=(v_c->>'school')::uuid;
 if cmd in ('state','history') then perform private.flow_share(v_cid);else perform pg_advisory_xact_lock(hashtextextended(v_cid::text,2401));end if;select * into v_gs from private.course_grade_state where course_id=v_cid;
 if cmd='history' then return jsonb_build_object('rows',(select coalesce(jsonb_agg(x order by x.created_at desc,x.id desc),'[]') from (select h.id,h.student_id,pr.full_name,h.kind,h.position,h.old_score,h.new_score,h.reason,h.created_at,coalesce(a.title,q.title) as title from private.grade_revisions h join public.profiles pr on pr.id=h.student_id and pr.status='active' left join public.learning_submission_versions v on v.id=h.version_id left join public.learning_submissions su on su.id=v.submission_id left join public.learning_assignments a on a.id=su.assignment_id left join public.learning_quiz_attempts at on at.id=h.attempt_id left join public.learning_quizzes q on q.id=at.quiz_id where h.course_id=v_cid and (nullif(v_d->>'student_id','') is null or h.student_id=(v_d->>'student_id')::uuid) and ((v_c->>'reviewer')::boolean or ((h.student_id=v_actor or (v_c->'children')@>to_jsonb(array[h.student_id])) and ((a.grades_visible and private.learning_published(a.status,a.publish_at)) or (q.grades_visible and q.status='published')))) order by h.created_at desc,h.id desc limit 26 offset v_off) x));end if;
 if cmd='state' then v_report:=private.weighted_report(jsonb_build_object('course',v_cid,'offset',v_off));for v_row in select * from jsonb_array_elements(v_report->'rows') loop v_metrics:='[]';
 for v_goal in select * from private.learning_goals where course_id=v_cid and active order by code,id loop
 select count(*),count(private.flow_effective(v_cid,l.kind,l.activity_id,(v_row->>'id')::uuid)),round(avg(private.flow_effective(v_cid,l.kind,l.activity_id,(v_row->>'id')::uuid)),2),coalesce(bool_and((private.flow_activity(v_cid,l.kind,l.activity_id,(v_row->>'id')::uuid)->>'visible')::boolean),false) into v_required,v_recorded,v_score,v_visible from private.goal_links l where l.goal_id=v_goal.id and l.kind in ('assignment','quiz');if not (v_c->>'reviewer')::boolean and not v_visible then v_score:=null;v_recorded:=0;end if;
 v_metrics:=v_metrics||jsonb_build_array(jsonb_build_object('goal_id',v_goal.id,'score',case when v_recorded=v_required and v_required>0 then v_score end,'assessed',v_recorded,'required',v_required,'mastered',case when v_recorded=v_required and v_required>0 and v_score is not null then v_score>=v_goal.threshold end,'materials_completed',(select count(*) from private.goal_links l join private.material_progress mp on mp.material_id=l.activity_id and mp.student_id=(v_row->>'id')::uuid where l.goal_id=v_goal.id and l.kind='material')));end loop;v_all:=v_all||jsonb_build_array(v_row||jsonb_build_object('goals',v_metrics));end loop;
 return jsonb_build_object('context',v_c,'can_unlock',((v_c->>'writable')::boolean and ((v_c->>'admin')::boolean or private.has_school_role(v_school,'principal'))),'locked',coalesce(v_gs.locked,false),'revision',coalesce(v_gs.revision,0),'finalizations',case when (v_c->>'reviewer')::boolean then (select coalesce(jsonb_agg(x order by x.created_at desc),'[]') from (select gf.id,gf.reason,gf.created_at from private.grade_finalizations gf where gf.course_id=v_cid order by gf.created_at desc limit 10) x) else '[]'::jsonb end,'goals',(select coalesce(jsonb_agg(to_jsonb(lg) order by code,id),'[]') from private.learning_goals lg where course_id=v_cid and (active or (v_c->>'manager')::boolean)),'links',(select coalesce(jsonb_agg(to_jsonb(l)),'[]') from private.goal_links l join private.learning_goals lg on lg.id=l.goal_id where lg.course_id=v_cid),'rows',v_all,'has_more',v_report->'has_more','activities',(select coalesce(jsonb_agg(x),'[]') from (select id,title,'material' as kind from public.learning_materials where teaching_class_id=v_cid and ((v_c->>'manager')::boolean or private.material_access(id)) union all select id,title,'assignment' from public.learning_assignments where teaching_class_id=v_cid and ((v_c->>'manager')::boolean or private.learning_published(status,publish_at)) union all select id,title,'quiz' from public.learning_quizzes where teaching_class_id=v_cid and ((v_c->>'manager')::boolean or status='published')) x),'followups',(select coalesce(jsonb_agg(x.data order by x.created_at desc),'[]') from (select (to_jsonb(sf)-array['result_score','base_signature','note'])||jsonb_build_object('full_name',pr.full_name,'result_score',case when (v_c->>'reviewer')::boolean or (private.flow_activity(v_cid,sf.activity_kind,sf.activity_id,sf.student_id)->>'visible')::boolean then sf.result_score end,'note',case when (v_c->>'reviewer')::boolean or (private.flow_activity(v_cid,sf.activity_kind,sf.activity_id,sf.student_id)->>'visible')::boolean then sf.note else '' end,'baseline_changed',(sf.base_signature is not null and sf.base_signature is distinct from private.flow_activity(v_cid,sf.activity_kind,sf.activity_id,sf.student_id)->>'signature')) as data,sf.created_at from private.study_followups sf join public.profiles pr on pr.id=sf.student_id and pr.status='active' where sf.course_id=v_cid and sf.student_id in (select (r->>'id')::uuid from jsonb_array_elements(v_all) r) order by sf.created_at desc,sf.id limit 200) x));end if;
 if not (v_c->>'writable')::boolean then raise exception 'Semester arsip atau kelas nonaktif bersifat baca-saja.';end if;
 if cmd='unlock' then if not (v_c->>'admin')::boolean and not private.has_school_role(v_school,'principal') then raise exception 'Hanya admin atau kepala madrasah dapat membuka nilai final.' using errcode='42501';end if;if v_gs.revision is distinct from v_rev or not coalesce(v_gs.locked,false) then raise exception 'Status nilai berubah. Muat ulang.';end if;if length(v_reason) not between 5 and 1000 then raise exception 'Alasan minimal 5 karakter.';end if;update private.course_grade_state set locked=false,revision=revision+1 where course_id=v_cid;
 else if not (v_c->>'manager')::boolean then raise exception 'Hanya pengampu atau admin dapat mengubah alur akademik.' using errcode='42501';end if;perform private.flow_assert_open(v_cid);
 if cmd='lock' then if coalesce(v_gs.revision,0)<>v_rev or length(v_reason) not between 5 and 1000 then raise exception 'Status berubah atau alasan finalisasi belum lengkap.';end if;v_all:='[]';v_idx:=0;loop v_page:=private.weighted_report(jsonb_build_object('course',v_cid,'offset',v_idx));v_all:=v_all||(v_page->'rows');exit when not (v_page->>'has_more')::boolean;v_idx:=v_idx+100;if v_idx>=10000 then raise exception 'Kelas terlalu besar; hubungi operator.';end if;end loop;
 if jsonb_array_length(v_all)=0 or exists(select 1 from jsonb_array_elements(v_all) x where x->>'weighted_final' is null) or exists(select 1 from public.learning_quiz_attempts a join public.learning_quizzes q on q.id=a.quiz_id where q.teaching_class_id=v_cid and a.status='working') then raise exception 'Finalisasi memerlukan peserta aktif, bobot, seluruh nilai lengkap dan tidak ada kuis berlangsung.';end if;
 insert into private.grade_finalizations(course_id,actor_id,reason) values(v_cid,v_actor,v_reason) returning id into v_fid;insert into private.final_grade_rows select v_fid,(x->>'id')::uuid,(x->>'weighted_final')::numeric from jsonb_array_elements(v_all) x;insert into private.course_grade_state(course_id,locked,revision,finalization_id) values(v_cid,true,1,v_fid) on conflict(course_id) do update set locked=true,revision=private.course_grade_state.revision+1,finalization_id=v_fid;
 elsif cmd='goal-save' then if v_target is null then insert into private.learning_goals(course_id,code,title,threshold) values(v_cid,v_d->>'code',v_d->>'title',(v_d->>'threshold')::numeric) returning id into v_target;else update private.learning_goals set code=v_d->>'code',title=v_d->>'title',threshold=(v_d->>'threshold')::numeric,active=(v_d->>'active')::boolean,revision=revision+1 where id=v_target and course_id=v_cid and revision=v_rev;if not found then raise exception 'Tujuan pembelajaran berubah. Muat ulang.';end if;end if;
 elsif cmd='goal-link' then select * into v_g from private.learning_goals where id=(v_d->>'goal_id')::uuid and course_id=v_cid for update;if not found or v_g.revision<>v_rev then raise exception 'Tujuan pembelajaran berubah. Muat ulang.';end if;v_kind:=v_d->>'kind';v_activity:=(v_d->>'activity_id')::uuid;
 if not exists(select 1 from public.learning_materials where id=v_activity and teaching_class_id=v_cid and v_kind='material' union all select 1 from public.learning_assignments where id=v_activity and teaching_class_id=v_cid and v_kind='assignment' union all select 1 from public.learning_quizzes where id=v_activity and teaching_class_id=v_cid and v_kind='quiz') then raise exception 'Aktivitas bukan milik kelas ini.';end if;if (v_d->>'linked')::boolean then insert into private.goal_links values(v_g.id,v_kind,v_activity) on conflict do nothing;else delete from private.goal_links where goal_id=v_g.id and kind=v_kind and activity_id=v_activity;end if;update private.learning_goals set revision=revision+1 where id=v_g.id;
 elsif cmd='followup-create' then if not exists(select 1 from public.student_enrollments e join public.profiles pr on pr.id=e.student_id and pr.status='active' where e.classroom_id=(v_c->>'classroom')::uuid and e.student_id=(v_d->>'student_id')::uuid and e.status='active') then raise exception 'Siswa bukan peserta aktif kelas ini.';end if;v_base:=private.flow_activity(v_cid,v_d->>'activity_kind',(v_d->>'activity_id')::uuid,(v_d->>'student_id')::uuid);if v_base->>'score' is null then raise exception 'Nilai awal harus tersedia sebelum membuat tindak lanjut.';end if;
 insert into private.study_followups(course_id,student_id,kind,activity_kind,activity_id,plan,due_on,policy,cap,created_by) values(v_cid,(v_d->>'student_id')::uuid,v_d->>'kind',v_d->>'activity_kind',(v_d->>'activity_id')::uuid,v_d->>'plan',(v_d->>'due_on')::date,v_d->>'policy',(v_d->>'cap')::numeric,v_actor) returning id into v_target;
 elsif cmd in ('followup-complete','followup-withdraw') then select * into v_f from private.study_followups where id=v_target and course_id=v_cid for update;if not found or v_f.revision<>v_rev then raise exception 'Tindak lanjut berubah. Muat ulang.';end if;if length(trim(coalesce(v_d->>'note','')))<5 then raise exception 'Catatan minimal 5 karakter.';end if;
 if cmd='followup-complete' then if v_f.status<>'planned' then raise exception 'Hasil sudah dicatat; tarik beralasan dan buat tindak lanjut baru untuk koreksi.';end if;v_base:=private.flow_activity(v_cid,v_f.activity_kind,v_f.activity_id,v_f.student_id);if v_base->>'score' is null then raise exception 'Nilai awal tidak tersedia.';end if;update private.study_followups set status='completed',base_signature=v_base->>'signature',result_score=(v_d->>'result_score')::numeric,note=v_d->>'note',revision=revision+1,updated_at=clock_timestamp() where id=v_target;
 else if v_f.status='withdrawn' then raise exception 'Tindak lanjut sudah ditarik.';end if;update private.study_followups set status='withdrawn',note=v_d->>'note',revision=revision+1,updated_at=clock_timestamp() where id=v_target;end if;
 else raise exception 'Tindakan tidak dikenal.';end if;end if;
 insert into public.audit_logs(school_id,actor_id,action,entity,entity_id,details) values(v_school,v_actor,'academic.flow.'||cmd,'teaching_classes',v_cid::text,jsonb_build_object('target',v_target,'reason',v_reason));return jsonb_build_object('id',v_target,'finalization_id',v_fid);end;$$;
create or replace function public.learning_command(cmd text,p jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$begin perform private.require_mfa();perform private.flow_share((p->>'course')::uuid);return private.learning_command(cmd,p);end;$$;
create or replace function public.advanced_command(cmd text,p jsonb default '{}') returns jsonb language plpgsql security invoker set search_path='' as $$begin perform private.require_mfa();perform private.flow_share((p->>'course')::uuid);return private.advanced_command(cmd,p);end;$$;
create or replace function public.quiz_command(cmd text,p jsonb default '{}') returns jsonb language plpgsql security invoker set search_path='' as $$begin perform private.require_mfa();perform private.flow_share((p->>'course')::uuid);perform set_config('lms.grade_reason',coalesce(p->'data'->>'reason',''),true);if cmd in ('list','edit','save','release') then return private.quiz_manage(cmd,p);elsif cmd in ('start','attempt','answers','finish','tab-event','essay-grade') then return private.quiz_attempt(cmd,p);elsif cmd='report' then return private.learning_report(p);else raise exception 'Tindakan tidak dikenal.';end if;end;$$;
revoke all on function private.flow_share(uuid),private.flow_assert_open(uuid),private.flow_guard(),private.flow_grade_audit(),private.flow_activity(uuid,text,uuid,uuid),private.flow_effective(uuid,text,uuid,uuid),private.flow_adjust_report(jsonb,uuid),private.learning_report_pre_flow(jsonb),private.weighted_report_pre_flow(jsonb),private.weighted_report(jsonb),private.learning_report(jsonb),private.flow_rollover_plan(uuid,uuid,uuid,text,uuid[]),private.flow_rollover(text,jsonb),private.academic_flow_command(text,jsonb) from public,anon,authenticated;
grant execute on function private.flow_share(uuid),private.academic_flow_command(text,jsonb),private.learning_report(jsonb) to authenticated,service_role;
grant execute on function private.flow_assert_open(uuid),private.flow_activity(uuid,text,uuid,uuid),private.flow_effective(uuid,text,uuid,uuid),private.flow_adjust_report(jsonb,uuid),private.learning_report_pre_flow(jsonb),private.weighted_report_pre_flow(jsonb),private.weighted_report(jsonb),private.flow_rollover_plan(uuid,uuid,uuid,text,uuid[]),private.flow_rollover(text,jsonb) to service_role;
create function public.academic_flow_command(cmd text,p jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select private.academic_flow_command(cmd,p);$$;revoke all on function public.academic_flow_command(text,jsonb) from public,anon;grant execute on function public.academic_flow_command(text,jsonb) to authenticated,service_role;
commit;
